import{_ as o,o as t,c as s,aA as a}from"./chunks/framework.3vLQJm4-.js";const u=JSON.parse('{"title":"How to locally build the MANTIS docs.","description":"","frontmatter":{},"headers":[],"relativePath":"Tutorials/BuildingDocs.md","filePath":"Tutorials/BuildingDocs.md","lastUpdated":null}'),i={name:"Tutorials/BuildingDocs.md"};function n(d,e,c,l,r,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="How-to-locally-build-the-MANTIS-docs." tabindex="-1">How to locally build the MANTIS docs. <a class="header-anchor" href="#How-to-locally-build-the-MANTIS-docs." aria-label="Permalink to &quot;How to locally build the MANTIS docs. {#How-to-locally-build-the-MANTIS-docs.}&quot;">​</a></h1><p>The main file structure of the the docs has now been created, so you only have to build the documentation. Fortunately, the heavy lifting will be done by <code>Julia</code> and/or <code>Python</code>.</p><p>For convenience, there is a bash script in the tools folder, <code>build_local_docs.sh</code>, that automates the process. Make sure to run the script starting in the main <code>Mantis</code> folder. Use</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bash tools/build_local_docs.sh</span></span></code></pre></div><p>If this does not work, or if you prefer to go through the steps yourself, you can use the following step-by-step guide.</p><p>To create the docs, follow these steps:</p><ul><li><p>Navigate to the <code>docs/</code> directory. If you open a terminal in the <code>Mantis</code> repo, this is a simple matter of executing</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd docs</span></span></code></pre></div><p>(or the equivalent on your system) in your terminal.</p></li><li><p>Next, run</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia --color=yes --project make.jl</span></span></code></pre></div><p>in this directory (you can leave the <code>--color=yes</code> option out if you don&#39;t want the printed output to be coloured). This will update (or generate if it doesn&#39;t exist yet) a <code>build/</code>-directory in the <code>docs/</code>-directory<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>. All <code>.html</code> files are generated here. <em>Make sure that you save all changes before running this command or you won&#39;t see the changes!</em> Should this step fail, see the next step.</p></li><li><p>If the dependencies of <code>Mantis</code> changed, the build may fail when building in the <code>docs/</code>-folder. This is because the <code>docs/</code>-folder defines its own julia environment, since the documentation may have different dependencies than <code>Mantis</code> itself. To update the environment, open a terminal in the <code>docs/</code>-directory and type <code>julia</code> to open julia. Enter the package manager by typing <code>]</code> and activate the current environment by typing <code>activate .</code>. The environment is shown in parenthesis &#39;()&#39; and should say &#39;docs&#39;. Type <code>dev ../../Mantis.jl</code> and execute this command. <strong>Note that <code>../../Mantis.jl</code> refers to the folder name. If you did not call this Mantis.jl, make sure to use to correct name.</strong> The environment will be updated so that the latest version of <code>Mantis</code> is available with its updated structure. Then you may also have to run <code>instantiate</code> to make sure the <code>docs\\</code>-environment is updated. You can now redo the previous step.</p></li><li><p>Then you need to create a (local) webserver to view the HTML docs, for which there are a few options, see the <a href="https://documenter.juliadocs.org/stable/man/guide/" target="_blank" rel="noreferrer">Documenter Docs</a>. Since I have <code>Python</code> installed, I use the python option. Run</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python -m http.server --bind localhost</span></span></code></pre></div><p>(after, in my case, activating my conda environment by executing <code>conda activate</code>) in the <code>docs/</code>-directory. You may have to use</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 -m http.server --bind localhost</span></span></code></pre></div><p>instead. Alternatively, you can use Julia with <code>LiveServer.jl</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>julia -e &#39;using LiveServer; serve(dir=&quot;build&quot;)</span></span></code></pre></div><p>Note that the automate script tries all these options for you.</p></li><li><p>In my case, this will result in VScode giving me the message: <code>Your application running on port 8000 is available. See all forwarded ports</code> with the options <code>Open in Browser</code> and <code>Preview in Editor</code>. Click the <code>Open in Browser</code>-option to see the html pages. You (may) have to click the <code>build/</code>-link when the browser opens.</p></li><li><p>Enjoy the <code>Mantis</code> docs!</p></li><li><p>In my case, this will result in VScode giving me the message: <code>Your application running on port 8000 is available. See all forwarded ports</code> with the options <code>Open in Browser</code> and <code>Preview in Editor</code>. Click the <code>Open in Browser</code>-option to see the html pages. You have to click the <code>build/</code>-link when the browser opens.</p></li><li><p>Enjoy the <code>Mantis</code> docs!</p></li><li><p>When done, you can kill the local webserver by using <code>Ctrl+C</code>.</p></li></ul><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>The <code>docs/build/</code>-folder should <strong>never</strong> be gitted. (See also the warning in the <a href="https://documenter.juliadocs.org/stable/man/guide/" target="_blank" rel="noreferrer">Documenter Docs</a>). The <code>.gitignore</code>-file is already setup to prevent this. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',9)])])}const g=o(i,[["render",n]]);export{u as __pageData,g as default};
